:root {
  /* Colors */
  --color-ink-black: #0d0d0d;
  --color-paper-white: #ffffff;
  --color-graphite: #333333;
  --color-signal-yellow: #ffd600;
  --color-alert-magenta: #ff0062;

  /* Typography — Font Families */
  --font-cofo-sans: 'Cofo Sans', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-arial: 'Arial', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-caption: 10px;
  --leading-caption: 1;
  --tracking-caption: -0.07px;
  --text-body: 14px;
  --leading-body: 1.43;
  --tracking-body: 0px;
  --text-subheading: 18px;
  --leading-subheading: 1.11;
  --tracking-subheading: -0.126px;
  --text-heading-sm: 22px;
  --leading-heading-sm: 1.1;
  --tracking-heading-sm: -0.154px;
  --text-display: 72px;
  --leading-display: 1;
  --tracking-display: -0.504px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-unit: 4px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-84: 84px;
  --spacing-120: 120px;
  --spacing-124: 124px;
  --spacing-136: 136px;
  --spacing-144: 144px;

  /* Layout */
  --page-max-width: 1200px;
  --section-gap: 84-124px;
  --card-padding: 24-26px;
  --element-gap: 16-20px;

  /* Border Radius */
  --radius-lg: 10px;
  --radius-2xl: 16px;

  /* Named Radii */
  --radius-blobs: irregular;
  --radius-cards: 10px;
  --radius-buttons: 16px;

  /* Surfaces */
  --surface-canvas: #ffffff;
  --surface-accent-bloom: #ffd600;
}
```

